    cart.add(productA, 2);
    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // refreshed price: 500 * 2 = 1000 subtotal
    // discount: 100 → discounted: 900
    // tax: 8% of 900 = 72
    // shipping: 200
    // total: 900 + 72 + 200 = 1172
