import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
  type WeightBracket,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 100, weightGrams },
  quantity,
});

const makeLineNoWeight = (id: string, quantity: number): CartLine => ({
  product: { id, name: id, unitPriceCents: 100 },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for items below threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 3000)).toBe(500);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 6000)).toBe(0);
    });

    it("returns flat fee when no threshold is configured", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 10000)).toBe(500);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 600 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty bracket list", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 for zero-weight items", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLineNoWeight("a", 2)], 1000),
      ).toBe(0);
    });

    it("selects lowest bracket for light items", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200g item
      expect(
        calc.computeShippingCents([makeLine("a", 200, 1)], 1000),
      ).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // exactly 500g
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 1000),
      ).toBe(300);
    });

    it("selects next bracket just above boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g → second bracket
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 1000),
      ).toBe(600);
    });

    it("selects highest bracket for heavy items within range", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 3000g
      expect(
        calc.computeShippingCents([makeLine("a", 3000, 1)], 1000),
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      // 6000g > 5000g
      expect(
        calc.computeShippingCents([makeLine("a", 6000, 1)], 1000),
      ).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow is set", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g > 5000g, no overflow → last bracket cost
      expect(
        calc.computeShippingCents([makeLine("a", 6000, 1)], 1000),
      ).toBe(1200);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 300g * 2 = 600g → second bracket (600)
      expect(
        calc.computeShippingCents([makeLine("a", 300, 2)], 1000),
      ).toBe(600);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unordered: WeightBracket[] = [
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      expect(
        calc.computeShippingCents([makeLine("a", 400, 1)], 1000),
      ).toBe(300);
    });
  });
});

